{
  "name": "Zenith 6x4 - Private Time Manager",
  "description": "A high-performance productivity tool based on the 6x4 time-blocking method (six 4-hour cycles). Features AI-driven insights, activity tracking, and a sleek private-zone aesthetic.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type ActivityType = 'Work' | 'Study' | 'Home' | 'Sleep' | 'Other';

export interface TimeBlock {
  id: number;
  label: string;
  startTime: string; // HH:mm
  endTime: string;   // HH:mm
}

export interface ActivityEntry {
  id: string;
  blockId: number;
  type: ActivityType;
  description: string;
  timestamp: number;
}

export interface AppState {
  activities: ActivityEntry[];
  currentView: 'dashboard' | 'stats' | 'coach';
}

import { TimeBlock, ActivityType } from './types';

export const BLOCKS: TimeBlock[] = [
  { id: 1, label: 'Block I: Foundation', startTime: '00:00', endTime: '04:00' },
  { id: 2, label: 'Block II: Awakening', startTime: '04:00', endTime: '08:00' },
  { id: 3, label: 'Block III: Prime I', startTime: '08:00', endTime: '12:00' },
  { id: 4, label: 'Block IV: Prime II', startTime: '12:00', endTime: '16:00' },
  { id: 5, label: 'Block V: Reflection', startTime: '16:00', endTime: '20:00' },
  { id: 6, label: 'Block VI: Resolution', startTime: '20:00', endTime: '00:00' },
];

export const ACTIVITY_TYPES: ActivityType[] = ['Work', 'Study', 'Home', 'Sleep', 'Other'];

export const ACTIVITY_COLORS: Record<ActivityType, string> = {
  Work: '#3b82f6',   // Blue
  Study: '#8b5cf6',  // Purple
  Home: '#10b981',   // Emerald
  Sleep: '#6366f1',  // Indigo
  Other: '#6b7280',  // Gray
};

import { GoogleGenAI, Type } from "@google/genai";
import { ActivityEntry } from "../types";
import { BLOCKS } from "../constants";

export async function getProductivityAnalysis(activities: ActivityEntry[]): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const summary = activities.map(a => {
    const block = BLOCKS.find(b => b.id === a.blockId);
    return `Block ${block?.label} (${block?.startTime}-${block?.endTime}): ${a.type} - ${a.description}`;
  }).join('\n');

  const prompt = `
    As a high-performance productivity coach, analyze my "6x4" (six 4-hour cycles) day structure based on these logs:

    ${summary || "No activities logged today."}

    Provide a concise, motivating analysis in Markdown. Focus on:
    1. Balance between deep work, study, and rest.
    2. Identification of patterns (e.g., are the morning blocks optimized?).
    3. Three specific, actionable tips to improve tomorrow's efficiency.

    Keep the tone professional, minimalist, and encouraging for a 'private zone' focus app.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 0 }
      }
    });
    return response.text || "Unable to generate insights at this time.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Error connecting to the Zenith Intelligence core. Please try again later.";
  }
}

import React from 'react';
import { TimeBlock, ActivityEntry, ActivityType } from '../types';
import { ACTIVITY_COLORS } from '../constants';

interface BlockCardProps {
  block: TimeBlock;
  activities: ActivityEntry[];
  isActive: boolean;
  onAdd: (blockId: number) => void;
}

const BlockCard: React.FC<BlockCardProps> = ({ block, activities, isActive, onAdd }) => {
  return (
    <div className={`p-4 rounded-2xl transition-all duration-300 ${isActive ? 'glass border-blue-500/50 active-ring' : 'glass border-white/5 opacity-80'}`}>
      <div className="flex justify-between items-start mb-3">
        <div>
          <h3 className={`font-bold text-sm uppercase tracking-wider ${isActive ? 'text-blue-400' : 'text-gray-400'}`}>
            {block.label}
          </h3>
          <p className="text-xs text-gray-500 mono">{block.startTime} — {block.endTime}</p>
        </div>
        {isActive && (
          <span className="flex h-2 w-2 rounded-full bg-blue-500 animate-pulse"></span>
        )}
      </div>

      <div className="space-y-2 min-h-[80px]">
        {activities.length === 0 ? (
          <p className="text-xs italic text-gray-600">No activity logged...</p>
        ) : (
          activities.map((a) => (
            <div key={a.id} className="flex items-center gap-2 text-xs">
              <div 
                className="w-1.5 h-1.5 rounded-full" 
                style={{ backgroundColor: ACTIVITY_COLORS[a.type] }}
              />
              <span className="font-semibold">{a.type}:</span>
              <span className="truncate text-gray-300">{a.description}</span>
            </div>
          ))
        )}
      </div>

      <button 
        onClick={() => onAdd(block.id)}
        className="mt-4 w-full py-2 bg-white/5 hover:bg-white/10 text-white text-xs rounded-lg transition-colors border border-white/5"
      >
        + Add Log
      </button>
    </div>
  );
};

export default BlockCard;

import React, { useState } from 'react';
import { ActivityType } from '../types';
import { ACTIVITY_TYPES, BLOCKS } from '../constants';

interface ActivityModalProps {
  blockId: number;
  onClose: () => void;
  onSave: (type: ActivityType, description: string) => void;
}

const ActivityModal: React.FC<ActivityModalProps> = ({ blockId, onClose, onSave }) => {
  const [type, setType] = useState<ActivityType>('Work');
  const [description, setDescription] = useState('');

  const block = BLOCKS.find(b => b.id === blockId);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
      <div className="w-full max-w-md glass p-6 rounded-3xl border border-white/10">
        <h2 className="text-xl font-bold mb-1">New Log Entry</h2>
        <p className="text-sm text-gray-500 mb-6">{block?.label}</p>

        <div className="space-y-4">
          <div>
            <label className="block text-xs uppercase text-gray-400 mb-2">Category</label>
            <div className="grid grid-cols-3 gap-2">
              {ACTIVITY_TYPES.map(t => (
                <button
                  key={t}
                  onClick={() => setType(t)}
                  className={`py-2 px-1 text-xs rounded-xl border transition-all ${
                    type === t 
                      ? 'bg-blue-600 border-blue-400 text-white' 
                      : 'bg-white/5 border-white/10 text-gray-400 hover:bg-white/10'
                  }`}
                >
                  {t}
                </button>
              ))}
            </div>
          </div>

          <div>
            <label className="block text-xs uppercase text-gray-400 mb-2">Description</label>
            <input
              type="text"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="What did you achieve?"
              className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 text-white"
            />
          </div>
        </div>

        <div className="flex gap-3 mt-8">
          <button 
            onClick={onClose}
            className="flex-1 py-3 text-sm text-gray-400 hover:text-white transition-colors"
          >
            Cancel
          </button>
          <button 
            onClick={() => onSave(type, description)}
            disabled={!description.trim()}
            className="flex-[2] py-3 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded-xl transition-all disabled:opacity-50 disabled:cursor-not-allowed"
          >
            Save Entry
          </button>
        </div>
      </div>
    </div>
  );
};

export default ActivityModal;

import React, { useState, useEffect, useMemo } from 'react';
import { ActivityEntry, ActivityType, AppState } from './types';
import { BLOCKS, ACTIVITY_COLORS } from './constants';
import BlockCard from './components/BlockCard';
import ActivityModal from './components/ActivityModal';
import { getProductivityAnalysis } from './services/geminiService';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip } from 'recharts';

const App: React.FC = () => {
  const [activities, setActivities] = useState<ActivityEntry[]>([]);
  const [currentView, setCurrentView] = useState<AppState['currentView']>('dashboard');
  const [activeModalBlock, setActiveModalBlock] = useState<number | null>(null);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [coachResponse, setCoachResponse] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('zenith_activities');
    if (saved) setActivities(JSON.parse(saved));

    const timer = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    localStorage.setItem('zenith_activities', JSON.stringify(activities));
  }, [activities]);

  const currentBlockId = useMemo(() => {
    const hours = currentTime.getHours();
    if (hours >= 0 && hours < 4) return 1;
    if (hours >= 4 && hours < 8) return 2;
    if (hours >= 8 && hours < 12) return 3;
    if (hours >= 12 && hours < 16) return 4;
    if (hours >= 16 && hours < 20) return 5;
    return 6;
  }, [currentTime]);

  const handleAddActivity = (type: ActivityType, description: string) => {
    if (activeModalBlock === null) return;
    const newEntry: ActivityEntry = {
      id: Math.random().toString(36).substr(2, 9),
      blockId: activeModalBlock,
      type,
      description,
      timestamp: Date.now(),
    };
    setActivities(prev => [...prev, newEntry]);
    setActiveModalBlock(null);
  };

  const getCoachAdvice = async () => {
    setIsAnalyzing(true);
    const advice = await getProductivityAnalysis(activities);
    setCoachResponse(advice);
    setIsAnalyzing(false);
  };

  const chartData = useMemo(() => {
    const counts = activities.reduce((acc, curr) => {
      acc[curr.type] = (acc[curr.type] || 0) + 1;
      return acc;
    }, {} as Record<string, number>);

    return Object.entries(counts).map(([name, value]) => ({ name, value }));
  }, [activities]);

  return (
    <div className="min-h-screen flex flex-col max-w-lg mx-auto pb-24">
      {/* Header */}
      <header className="p-6 pt-10 sticky top-0 z-40 bg-[#0a0a0a]/80 backdrop-blur-md">
        <div className="flex justify-between items-end">
          <div>
            <h1 className="text-3xl font-black tracking-tighter text-white">ZENITH</h1>
            <p className="text-xs text-blue-500 font-bold tracking-widest uppercase mt-1">6x4 Private Zone</p>
          </div>
          <div className="text-right">
            <p className="text-2xl font-bold mono text-white">
              {currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false })}
            </p>
            <p className="text-[10px] text-gray-500 uppercase tracking-widest">System Operational</p>
          </div>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 p-4">
        {currentView === 'dashboard' && (
          <div className="grid grid-cols-1 gap-4">
            {BLOCKS.map(block => (
              <BlockCard 
                key={block.id}
                block={block}
                activities={activities.filter(a => a.blockId === block.id)}
                isActive={block.id === currentBlockId}
                onAdd={setActiveModalBlock}
              />
            ))}
          </div>
        )}

        {currentView === 'stats' && (
          <div className="space-y-6">
            <div className="glass p-6 rounded-3xl border border-white/5">
              <h2 className="text-lg font-bold mb-4">Activity Mix</h2>
              {chartData.length > 0 ? (
                <div className="h-64">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie
                        data={chartData}
                        innerRadius={60}
                        outerRadius={80}
                        paddingAngle={5}
                        dataKey="value"
                      >
                        {chartData.map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={ACTIVITY_COLORS[entry.name as ActivityType]} />
                        ))}
                      </Pie>
                      <Tooltip 
                        contentStyle={{ backgroundColor: '#171717', border: '1px solid #333' }}
                        itemStyle={{ color: '#fff' }}
                      />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
              ) : (
                <p className="text-center text-gray-500 py-10">Log some activities to see your distribution.</p>
              )}
            </div>

            <div className="glass p-6 rounded-3xl border border-white/5">
              <h2 className="text-lg font-bold mb-4">History</h2>
              <div className="space-y-3">
                {activities.slice().reverse().map(a => (
                   <div key={a.id} className="flex justify-between items-center text-sm p-3 bg-white/5 rounded-xl border border-white/5">
                      <div className="flex items-center gap-3">
                        <div className="w-2 h-2 rounded-full" style={{ backgroundColor: ACTIVITY_COLORS[a.type] }} />
                        <div>
                          <p className="font-bold text-gray-200">{a.type}</p>
                          <p className="text-xs text-gray-500">{a.description}</p>
                        </div>
                      </div>
                      <span className="text-[10px] text-gray-600 mono">
                        {new Date(a.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </span>
                   </div>
                ))}
                {activities.length === 0 && <p className="text-xs text-gray-600 text-center">Your log history is empty.</p>}
              </div>
            </div>
          </div>
        )}

        {currentView === 'coach' && (
          <div className="space-y-6">
            <div className="glass p-6 rounded-3xl border border-blue-500/30">
              <h2 className="text-lg font-bold mb-2">Zenith Intelligence</h2>
              <p className="text-xs text-gray-400 mb-6">AI-driven cycle optimization and performance coaching.</p>

              {!coachResponse && !isAnalyzing && (
                <button 
                  onClick={getCoachAdvice}
                  className="w-full py-4 bg-blue-600 hover:bg-blue-500 text-white font-black rounded-2xl transition-all shadow-lg shadow-blue-900/20"
                >
                  GENERATE DAILY INSIGHTS
                </button>
              )}

              {isAnalyzing && (
                <div className="py-10 text-center space-y-4">
                  <div className="inline-block w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                  <p className="text-sm text-blue-400 font-bold animate-pulse uppercase tracking-widest">Analyzing Human Behavior Patterns...</p>
                </div>
              )}

              {coachResponse && !isAnalyzing && (
                <div className="prose prose-invert prose-sm max-w-none space-y-4 text-gray-300">
                  <div className="p-4 bg-white/5 rounded-xl border border-white/10 leading-relaxed whitespace-pre-wrap">
                    {coachResponse}
                  </div>
                  <button 
                    onClick={() => setCoachResponse(null)}
                    className="w-full py-2 text-xs text-gray-500 hover:text-white transition-colors"
                  >
                    Reset Analysis
                  </button>
                </div>
              )}
            </div>
          </div>
        )}
      </main>

      {/* Navigation Footer */}
      <nav className="fixed bottom-0 left-0 right-0 h-20 bg-[#0a0a0a]/90 backdrop-blur-xl border-t border-white/5 flex items-center justify-around px-6 z-50">
        <button 
          onClick={() => setCurrentView('dashboard')}
          className={`flex flex-col items-center gap-1 transition-colors ${currentView === 'dashboard' ? 'text-blue-500' : 'text-gray-600 hover:text-gray-400'}`}
        >
          <div className="w-6 h-6 flex items-center justify-center">
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect width="18" height="18" x="3" y="3" rx="2"/><path d="M3 9h18"/><path d="M9 21V9"/></svg>
          </div>
          <span className="text-[10px] font-bold uppercase tracking-widest">Focus</span>
        </button>

        <button 
          onClick={() => setCurrentView('stats')}
          className={`flex flex-col items-center gap-1 transition-colors ${currentView === 'stats' ? 'text-emerald-500' : 'text-gray-600 hover:text-gray-400'}`}
        >
          <div className="w-6 h-6 flex items-center justify-center">
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 3v18h18"/><path d="m19 9-5 5-4-4-3 3"/></svg>
          </div>
          <span className="text-[10px] font-bold uppercase tracking-widest">Stats</span>
        </button>

        <button 
          onClick={() => setCurrentView('coach')}
          className={`flex flex-col items-center gap-1 transition-colors ${currentView === 'coach' ? 'text-purple-500' : 'text-gray-600 hover:text-gray-400'}`}
        >
          <div className="w-6 h-6 flex items-center justify-center">
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 2a10 10 0 1 0 10 10 4 4 0 0 1-5-5 4 4 0 0 1-5-5"/><path d="M8.5 8.5 4.5 4.5"/><path d="M15.5 15.5 19.5 19.5"/></svg>
          </div>
          <span className="text-[10px] font-bold uppercase tracking-widest">Coach</span>
        </button>
      </nav>

      {/* Modals */}
      {activeModalBlock !== null && (
        <ActivityModal 
          blockId={activeModalBlock}
          onClose={() => setActiveModalBlock(null)}
          onSave={handleAddActivity}
        />
      )}
    </div>
  );
};

export default App;

{
  "name": "Karam-Charak - 6x4 Time Manager",
  "description": "A high-performance productivity tool based on the 6x4 time-blocking method. Features AI-driven insights, task tracking, and rescheduling logic.",
  "requestFramePermissions": []
}

export type ActivityType = 'Work' | 'Study' | 'Home' | 'Sleep' | 'Other';
export type ActivityStatus = 'Pending' | 'Completed' | 'Rescheduled';

export interface TimeBlock {
  id: number;
  label: string;
  startTime: string; // HH:mm
  endTime: string;   // HH:mm
}

export interface ActivityEntry {
  id: string;
  blockId: number;
  type: ActivityType;
  description: string;
  timestamp: number;
  estimatedDuration: number; // minutes
  status: ActivityStatus;
  originalBlockId?: number; // For tracking reschedules
}

export interface AppState {
  activities: ActivityEntry[];
  currentView: 'dashboard' | 'stats' | 'coach';
}

import { GoogleGenAI, Type } from "@google/genai";
import { ActivityEntry } from "../types";
import { BLOCKS } from "../constants";

export async function getProductivityAnalysis(activities: ActivityEntry[]): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const summary = activities.map(a => {
    const block = BLOCKS.find(b => b.id === a.blockId);
    const statusText = a.status === 'Completed' ? '✅' : (a.status === 'Rescheduled' ? '⏭️' : '⏳');
    return `Block ${block?.label} (${block?.startTime}-${block?.endTime}): ${a.type} - ${a.description} (${a.estimatedDuration}m) [${statusText} ${a.status}]`;
  }).join('\n');

  const prompt = `
    As "Karam-Charak", a high-performance productivity philosopher and coach, analyze my "6x4" (six 4-hour cycles) day structure:

    ${summary || "No activities logged today."}

    Provide a professional, stoic, and insightful analysis in Markdown. Focus on:
    1. Completion rate vs Rescheduling patterns.
    2. Alignment of difficult tasks (Work/Study) with prime cycles.
    3. Three specific, actionable "Karam" (actions) to optimize tomorrow.

    Keep the tone minimalist, grounded, and focused on self-mastery.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 0 }
      }
    });
    return response.text || "Karam-Charak intelligence is currently offline.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Error connecting to the Karam-Charak wisdom core.";
  }
}

import React from 'react';
import { TimeBlock, ActivityEntry, ActivityStatus } from '../types';
import { ACTIVITY_COLORS } from '../constants';

interface BlockCardProps {
  block: TimeBlock;
  activities: ActivityEntry[];
  isActive: boolean;
  onAdd: (blockId: number) => void;
  onUpdateStatus: (activityId: string, status: ActivityStatus) => void;
  onReschedule: (activityId: string) => void;
}

const BlockCard: React.FC<BlockCardProps> = ({ block, activities, isActive, onAdd, onUpdateStatus, onReschedule }) => {
  return (
    <div className={`p-4 rounded-2xl transition-all duration-300 ${isActive ? 'glass border-blue-500/50 active-ring' : 'glass border-white/5 opacity-80'}`}>
      <div className="flex justify-between items-start mb-3">
        <div>
          <h3 className={`font-bold text-sm uppercase tracking-wider ${isActive ? 'text-blue-400' : 'text-gray-400'}`}>
            {block.label}
          </h3>
          <p className="text-xs text-gray-500 mono">{block.startTime} — {block.endTime}</p>
        </div>
        {isActive && (
          <span className="flex h-2 w-2 rounded-full bg-blue-500 animate-pulse"></span>
        )}
      </div>

      <div className="space-y-3 min-h-[60px]">
        {activities.length === 0 ? (
          <p className="text-xs italic text-gray-600">Cycle clear...</p>
        ) : (
          activities.map((a) => (
            <div key={a.id} className="flex flex-col gap-1 p-2 rounded-xl bg-white/5 border border-white/5">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2 text-xs">
                  <div 
                    className="w-1.5 h-1.5 rounded-full" 
                    style={{ backgroundColor: ACTIVITY_COLORS[a.type] }}
                  />
                  <span className={`font-bold ${a.status === 'Completed' ? 'line-through opacity-50' : ''}`}>{a.type}</span>
                  <span className="text-[10px] text-gray-500 mono">{a.estimatedDuration}m remaining</span>
                </div>
                <div className="flex gap-1">
                  {a.status === 'Pending' && (
                    <>
                      <button 
                        onClick={() => onUpdateStatus(a.id, 'Completed')}
                        className="p-1 hover:bg-emerald-500/20 text-emerald-500 rounded transition-colors"
                        title="Mark Complete"
                      >
                        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><polyline points="20 6 9 17 4 12"/></svg>
                      </button>
                      <button 
                        onClick={() => onReschedule(a.id)}
                        className="p-1 hover:bg-orange-500/20 text-orange-500 rounded transition-colors"
                        title="Reschedule"
                      >
                        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="M5 12h14"/><path d="m12 5 7 7-7 7"/></svg>
                      </button>
                    </>
                  )}
                  {a.status === 'Completed' && (
                    <span className="text-[10px] text-emerald-500 font-bold px-1 uppercase tracking-tighter">Done</span>
                  )}
                  {a.status === 'Rescheduled' && (
                    <span className="text-[10px] text-orange-400 font-bold px-1 uppercase tracking-tighter">Moved</span>
                  )}
                </div>
              </div>
              <p className={`text-xs text-gray-300 truncate pl-3.5 ${a.status === 'Completed' ? 'opacity-40' : ''}`}>
                {a.description}
              </p>
            </div>
          ))
        )}
      </div>

      <button 
        onClick={() => onAdd(block.id)}
        className="mt-4 w-full py-2 bg-white/5 hover:bg-white/10 text-white text-xs rounded-lg transition-colors border border-white/5 flex items-center justify-center gap-2"
      >
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
