import React, { useState, useEffect, useMemo } from 'react';
import { ActivityEntry, ActivityType, ActivityStatus, AppState } from './types';
import { BLOCKS, ACTIVITY_COLORS } from './constants';
import BlockCard from './components/BlockCard';
import ActivityModal from './components/ActivityModal';
import { getProductivityAnalysis } from './services/geminiService';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip } from 'recharts';

const App: React.FC = () => {
  const [activities, setActivities] = useState<ActivityEntry[]>([]);
  const [currentView, setCurrentView] = useState<AppState['currentView']>('dashboard');
  const [activeModalBlock, setActiveModalBlock] = useState<number | null>(null);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [coachResponse, setCoachResponse] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('karam_charak_activities');
    if (saved) setActivities(JSON.parse(saved));

    const timer = setInterval(() => setCurrentTime(new Date()), 10000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    localStorage.setItem('karam_charak_activities', JSON.stringify(activities));
  }, [activities]);

  const currentBlockId = useMemo(() => {
    const hours = currentTime.getHours();
    if (hours >= 0 && hours < 4) return 1;
    if (hours >= 4 && hours < 8) return 2;
    if (hours >= 8 && hours < 12) return 3;
    if (hours >= 12 && hours < 16) return 4;
    if (hours >= 16 && hours < 20) return 5;
    return 6;
  }, [currentTime]);

  const handleAddActivity = (type: ActivityType, description: string, duration: number) => {
    if (activeModalBlock === null) return;
    const newEntry: ActivityEntry = {
      id: Math.random().toString(36).substr(2, 9),
      blockId: activeModalBlock,
      type,
      description,
      timestamp: Date.now(),
      estimatedDuration: duration,
      status: 'Pending',
    };
    setActivities(prev => [...prev, newEntry]);
    setActiveModalBlock(null);
  };

  const updateActivityStatus = (id: string, status: ActivityStatus) => {
    setActivities(prev => prev.map(a => a.id === id ? { ...a, status } : a));
  };

  const handleReschedule = (id: string) => {
    setActivities(prev => {
      const activity = prev.find(a => a.id === id);
      if (!activity) return prev;

      // Logic: Reschedule to the NEXT block, or if it's the last block, tomorrow's first block
      let nextBlockId = activity.blockId + 1;
      if (nextBlockId > 6) nextBlockId = 1;

      const reschedEntry: ActivityEntry = {
        ...activity,
        id: Math.random().toString(36).substr(2, 9),
        blockId: nextBlockId,
        originalBlockId: activity.blockId,
        status: 'Pending',
        timestamp: Date.now(),
      };

      // Mark original as rescheduled
      return prev.map(a => a.id === id ? { ...a, status: 'Rescheduled' } : a).concat(reschedEntry);
    });
  };

  const getCoachAdvice = async () => {
    setIsAnalyzing(true);
    const advice = await getProductivityAnalysis(activities);
    setCoachResponse(advice);
    setIsAnalyzing(false);
  };

  const chartData = useMemo(() => {
    const counts = activities.filter(a => a.status === 'Completed').reduce((acc, curr) => {
      acc[curr.type] = (acc[curr.type] || 0) + 1;
      return acc;
    }, {} as Record<string, number>);

    return Object.entries(counts).map(([name, value]) => ({ name, value }));
  }, [activities]);

  const completionRate = useMemo(() => {
    if (activities.length === 0) return 0;
    const completed = activities.filter(a => a.status === 'Completed').length;
    return Math.round((completed / activities.length) * 100);
  }, [activities]);

  return (
    <div className="min-h-screen flex flex-col max-w-lg mx-auto pb-24 selection:bg-blue-500/30">
      {/* Header */}
      <header className="p-6 pt-10 sticky top-0 z-40 bg-[#0a0a0a]/80 backdrop-blur-md border-b border-white/5">
        <div className="flex justify-between items-end">
          <div>
            <h1 className="text-3xl font-black tracking-tighter text-white">KARAM-CHARAK</h1>
            <p className="text-[10px] text-blue-500 font-bold tracking-[0.3em] uppercase mt-1">Ethical Efficiency Core</p>
          </div>
          <div className="text-right">
            <p className="text-2xl font-bold mono text-white leading-none">
              {currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false })}
            </p>
            <p className="text-[9px] text-gray-500 uppercase tracking-widest mt-1">Status: Balanced</p>
          </div>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 p-4">
        {currentView === 'dashboard' && (
          <div className="space-y-4">
            <div className="glass p-4 rounded-2xl flex items-center justify-between border-blue-500/20">
               <div className="flex flex-col">
                  <span className="text-[10px] uppercase font-black text-gray-500 tracking-widest">Daily Completion</span>
                  <span className="text-2xl font-black text-white">{completionRate}%</span>
               </div>
               <div className="w-12 h-12 rounded-full border-4 border-white/5 flex items-center justify-center relative">
                  <svg className="w-full h-full transform -rotate-90">
                    <circle 
                      cx="24" cy="24" r="18" 
                      fill="transparent" 
                      stroke="currentColor" 
                      strokeWidth="4" 
                      className="text-blue-500"
                      strokeDasharray={`${(completionRate / 100) * 113} 113`}
                    />
                  </svg>
               </div>
            </div>

            <div className="grid grid-cols-1 gap-4">
              {BLOCKS.map(block => (
                <BlockCard 
                  key={block.id}
                  block={block}
                  activities={activities.filter(a => a.blockId === block.id)}
                  isActive={block.id === currentBlockId}
                  onAdd={setActiveModalBlock}
                  onUpdateStatus={updateActivityStatus}
                  onReschedule={handleReschedule}
                />
              ))}
            </div>
          </div>
        )}

        {currentView === 'stats' && (
          <div className="space-y-6">
            <div className="glass p-6 rounded-3xl border border-white/5">
              <h2 className="text-sm font-black uppercase tracking-widest text-gray-400 mb-4">Completed Cycles</h2>
              {chartData.length > 0 ? (
                <div className="h-64">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie
                        data={chartData}
                        innerRadius={60}
                        outerRadius={80}
                        paddingAngle={5}
                        dataKey="value"
                        animationDuration={1000}
                      >
                        {chartData.map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={ACTIVITY_COLORS[entry.name as ActivityType]} />
                        ))}
                      </Pie>
                      <Tooltip 
                        contentStyle={{ backgroundColor: '#171717', border: '1px solid #333', borderRadius: '12px' }}
                        itemStyle={{ color: '#fff', fontSize: '12px' }}
                      />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
              ) : (
                <p className="text-center text-xs text-gray-500 py-10 italic">No completed actions found in history.</p>
              )}
            </div>

            <div className="glass p-6 rounded-3xl border border-white/5">
              <h2 className="text-sm font-black uppercase tracking-widest text-gray-400 mb-4">Action Log</h2>
              <div className="space-y-3">
                {activities.slice().reverse().map(a => (
                   <div key={a.id} className="flex justify-between items-center text-sm p-3 bg-white/5 rounded-xl border border-white/5">
                      <div className="flex items-center gap-3">
                        <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: ACTIVITY_COLORS[a.type] }} />
                        <div>
                          <p className={`font-bold text-gray-200 ${a.status === 'Completed' ? 'opacity-40' : ''}`}>{a.type}</p>
                          <p className="text-[10px] text-gray-500">{a.description}</p>
                        </div>
                      </div>
                      <div className="text-right">
                         <span className={`text-[9px] font-black px-2 py-0.5 rounded uppercase ${
                           a.status === 'Completed' ? 'bg-emerald-500/20 text-emerald-400' : 
                           a.status === 'Rescheduled' ? 'bg-orange-500/20 text-orange-400' : 'bg-gray-500/20 text-gray-400'
                         }`}>
                           {a.status}
                         </span>
                         <p className="text-[8px] text-gray-600 mt-1 mono">{new Date(a.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
                      </div>
                   </div>
                ))}
                {activities.length === 0 && <p className="text-xs text-gray-600 text-center py-4">The scroll of Karam is empty.</p>}
              </div>
            </div>
          </div>
        )}

        {currentView === 'coach' && (
          <div className="space-y-6">
            <div className="glass p-6 rounded-3xl border border-blue-500/30">
              <h2 className="text-lg font-black tracking-tight mb-2">Insight Generator</h2>
              <p className="text-[10px] uppercase font-bold text-gray-500 mb-6 tracking-widest">Karam-Charak Philosophical Analysis</p>

              {!coachResponse && !isAnalyzing && (
                <button 
                  onClick={getCoachAdvice}
                  className="w-full py-5 bg-white text-black font-black rounded-2xl transition-all shadow-xl hover:scale-[1.02] active:scale-95 uppercase tracking-widest text-xs"
                >
                  Seek Wisdom
                </button>
              )}

              {isAnalyzing && (
                <div className="py-12 text-center space-y-6">
                  <div className="inline-block relative">
                     <div className="w-12 h-12 border-2 border-blue-500/20 rounded-full"></div>
                     <div className="absolute inset-0 border-t-2 border-blue-500 rounded-full animate-spin"></div>
                  </div>
                  <p className="text-[10px] text-blue-400 font-black animate-pulse uppercase tracking-[0.4em]">Deciphering Intentions...</p>
                </div>
              )}

              {coachResponse && !isAnalyzing && (
                <div className="animate-in fade-in duration-700">
                  <div className="p-5 bg-white/5 rounded-2xl border border-white/10 leading-relaxed text-sm text-gray-300 font-medium">
                    {coachResponse.split('\n').map((line, i) => (
                       <p key={i} className="mb-2 last:mb-0">{line}</p>
                    ))}
                  </div>
                  <button 
                    onClick={() => setCoachResponse(null)}
                    className="w-full py-4 mt-4 text-[10px] uppercase font-black text-gray-600 hover:text-white transition-colors tracking-widest"
                  >
                    Clear Reflection
                  </button>
                </div>
              )}
            </div>
          </div>
        )}
      </main>

      {/* Navigation Footer */}
      <nav className="fixed bottom-0 left-0 right-0 h-20 bg-[#0a0a0a]/90 backdrop-blur-xl border-t border-white/5 flex items-center justify-around px-6 z-50">
        <button 
          onClick={() => setCurrentView('dashboard')}
          className={`flex flex-col items-center gap-1 transition-all ${currentView === 'dashboard' ? 'text-blue-500 scale-110' : 'text-gray-600 hover:text-gray-400'}`}
        >
          <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><rect width="18" height="18" x="3" y="3" rx="2"/><path d="M3 9h18"/><path d="M9 21V9"/></svg>
          <span className="text-[9px] font-black uppercase tracking-[0.2em]">Karam</span>
        </button>

        <button 
          onClick={() => setCurrentView('stats')}
          className={`flex flex-col items-center gap-1 transition-all ${currentView === 'stats' ? 'text-emerald-500 scale-110' : 'text-gray-600 hover:text-gray-400'}`}
        >
          <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M3 3v18h18"/><path d="m19 9-5 5-4-4-3 3"/></svg>
          <span className="text-[9px] font-black uppercase tracking-[0.2em]">Charak</span>
        </button>

        <button 
          onClick={() => setCurrentView('coach')}
          className={`flex flex-col items-center gap-1 transition-all ${currentView === 'coach' ? 'text-purple-500 scale-110' : 'text-gray-600 hover:text-gray-400'}`}
        >
          <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><path d="M12 16v-4"/><path d="M12 8h.01"/></svg>
          <span className="text-[9px] font-black uppercase tracking-[0.2em]">Wisdom</span>
        </button>
      </nav>

      {/* Modals */}
      {activeModalBlock !== null && (
        <ActivityModal 
          blockId={activeModalBlock}
          onClose={() => setActiveModalBlock(null)}
          onSave={handleAddActivity}
        />
      )}
    </div>
  );
};

