                <label className="block text-[10px] uppercase text-gray-600 font-black mb-2 tracking-widest">Minutes (Est)</label>
                <input
                  type="number"
                  value={duration}
                  onChange={(e) => setDuration(e.target.value)}
                  className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-1 focus:ring-blue-500 text-white mono"
                />
             </div>
             <div>
                <label className="block text-[10px] uppercase text-gray-600 font-black mb-2 tracking-widest">Overtime (Min)</label>
                <input
                  type="number"
                  value={overtime}
                  onChange={(e) => setOvertime(e.target.value)}
                  className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-1 focus:ring-orange-500 text-white mono"
                />
             </div>
          </div>

          <div>
            <label className="block text-[10px] uppercase text-gray-600 font-black mb-3 tracking-widest">Batch Duplication</label>
            <div className="flex gap-4">
              <label className="flex items-center gap-2 cursor-pointer group">
                <input 
                  type="checkbox" 
                  checked={repeatMode === 'weekdays'} 
                  onChange={() => setRepeatMode(prev => prev === 'weekdays' ? 'none' : 'weekdays')}
                  className="w-4 h-4 rounded border-white/10 bg-white/5 text-blue-500 focus:ring-blue-500"
                />
                <span className="text-xs text-gray-400 group-hover:text-white transition-colors">Weekdays</span>
              </label>
              <label className="flex items-center gap-2 cursor-pointer group">
                <input 
                  type="checkbox" 
                  checked={repeatMode === 'weekends'} 
                  onChange={() => setRepeatMode(prev => prev === 'weekends' ? 'none' : 'weekends')}
                  className="w-4 h-4 rounded border-white/10 bg-white/5 text-blue-500 focus:ring-blue-500"
                />
                <span className="text-xs text-gray-400 group-hover:text-white transition-colors">Weekends</span>
              </label>
            </div>
          </div>
        </div>

        <div className="flex gap-3 mt-10">
          <button 
            onClick={onClose}
            className="flex-1 py-3 text-[10px] text-gray-500 hover:text-white transition-colors uppercase font-black tracking-widest"
          >
            Discard
          </button>
          <button 
            onClick={() => onSave(type, description, parseInt(duration) || 0, parseInt(overtime) || 0, repeatMode)}
            disabled={!description.trim()}
            className="flex-[2] py-4 bg-white text-black font-black rounded-2xl transition-all disabled:opacity-50 disabled:cursor-not-allowed uppercase tracking-widest text-[10px]"
          >
            Commit Cycle
          </button>
        </div>
      </div>
    </div>
  );
};

export default ActivityModal;

import React, { useState, useEffect, useMemo } from 'react';
import { ActivityEntry, ActivityType, ActivityStatus, AppState } from './types';
import { BLOCKS, ACTIVITY_COLORS } from './constants';
import BlockCard from './components/BlockCard';
import ActivityModal from './components/ActivityModal';
import { getProductivityAnalysis } from './services/geminiService';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip } from 'recharts';

const App: React.FC = () => {
  const [activities, setActivities] = useState<ActivityEntry[]>([]);
  const [currentView, setCurrentView] = useState<AppState['currentView']>('dashboard');
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [activeModalBlock, setActiveModalBlock] = useState<number | null>(null);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [coachResponse, setCoachResponse] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('karma_chakra_activities_v2');
    if (saved) setActivities(JSON.parse(saved));

    const timer = setInterval(() => setCurrentTime(new Date()), 10000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    localStorage.setItem('karma_chakra_activities_v2', JSON.stringify(activities));
  }, [activities]);

  const currentBlockId = useMemo(() => {
    const hours = currentTime.getHours();
    if (hours >= 0 && hours < 4) return 1;
    if (hours >= 4 && hours < 8) return 2;
    if (hours >= 8 && hours < 12) return 3;
    if (hours >= 12 && hours < 16) return 4;
    if (hours >= 16 && hours < 20) return 5;
    return 6;
  }, [currentTime]);

  const stats = useMemo(() => {
    const currentMins = currentTime.getHours() * 60 + currentTime.getMinutes();
    const totalMins = 24 * 60;
    const remainingMins = totalMins - currentMins;

    const format = (m: number) => {
      const h = Math.floor(m / 60);
      const min = m % 60;
      return `${h.toString().padStart(2, '0')}:${min.toString().padStart(2, '0')}`;
    };

    return {
      total: '24:00',
      current: format(currentMins),
      remaining: format(remainingMins),
      percentPassed: (currentMins / totalMins) * 100
    };
  }, [currentTime]);

  const handleAddActivity = (type: ActivityType, description: string, duration: number, overtime: number, repeatMode: 'none' | 'weekdays' | 'weekends') => {
    if (activeModalBlock === null) return;

    const datesToCreate: string[] = [selectedDate];

    if (repeatMode !== 'none') {
      const baseDate = new Date(selectedDate);
      const year = baseDate.getFullYear();
      const month = baseDate.getMonth();
      const day = baseDate.getDate();

      // Find the start of the week (Monday)
      const dayOfWeek = baseDate.getDay(); // 0 is Sun, 1 is Mon
      const diff = baseDate.getDate() - dayOfWeek + (dayOfWeek === 0 ? -6 : 1);
      const startOfWeek = new Date(baseDate.setDate(diff));

      for (let i = 0; i < 7; i++) {
        const d = new Date(startOfWeek);
        d.setDate(startOfWeek.getDate() + i);
        const dateStr = d.toISOString().split('T')[0];
        if (dateStr === selectedDate) continue; // Already added

        const isWeekend = d.getDay() === 0 || d.getDay() === 6;
        if (repeatMode === 'weekdays' && !isWeekend) datesToCreate.push(dateStr);
        if (repeatMode === 'weekends' && isWeekend) datesToCreate.push(dateStr);
      }
    }

    const newEntries: ActivityEntry[] = datesToCreate.map(date => ({
      id: Math.random().toString(36).substr(2, 9),
      blockId: activeModalBlock,
      date,
      type,
      description,
      timestamp: Date.now(),
      estimatedDuration: duration,
      overtime: overtime,
      status: 'Pending',
    }));

    setActivities(prev => [...prev, ...newEntries]);
    setActiveModalBlock(null);
  };

  const updateActivityStatus = (id: string, status: ActivityStatus) => {
    setActivities(prev => prev.map(a => a.id === id ? { ...a, status } : a));
  };

  const handleReschedule = (id: string) => {
    setActivities(prev => {
      const activity = prev.find(a => a.id === id);
      if (!activity) return prev;

      let nextBlockId = activity.blockId + 1;
      let targetDate = activity.date;

      if (nextBlockId > 6) {
        nextBlockId = 1;
        const d = new Date(activity.date);
        d.setDate(d.getDate() + 1);
        targetDate = d.toISOString().split('T')[0];
      }

      const reschedEntry: ActivityEntry = {
        ...activity,
        id: Math.random().toString(36).substr(2, 9),
        blockId: nextBlockId,
        date: targetDate,
        originalBlockId: activity.blockId,
        status: 'Pending',
        timestamp: Date.now(),
      };

      return prev.map(a => a.id === id ? { ...a, status: 'Rescheduled' } : a).concat(reschedEntry);
    });
  };

  const completionRate = useMemo(() => {
    const dayActivities = activities.filter(a => a.date === selectedDate);
    if (dayActivities.length === 0) return 0;
    const completed = dayActivities.filter(a => a.status === 'Completed').length;
    return Math.round((completed / dayActivities.length) * 100);
  }, [activities, selectedDate]);

  const filteredActivities = useMemo(() => {
    return activities.filter(a => a.date === selectedDate);
  }, [activities, selectedDate]);

  const getCoachAdvice = async () => {
    setIsAnalyzing(true);
    const advice = await getProductivityAnalysis(filteredActivities);
    setCoachResponse(advice);
    setIsAnalyzing(false);
  };

  return (
    <div className="min-h-screen flex flex-col max-w-lg mx-auto pb-24 selection:bg-blue-500/30">
      {/* Header with Enhanced Time Stats */}
      <header className="p-6 pt-10 sticky top-0 z-40 bg-[#0a0a0a]/90 backdrop-blur-xl border-b border-white/5">
        <div className="flex justify-between items-start mb-6">
          <div>
            <h1 className="text-3xl font-black tracking-tighter text-white leading-none">KARMA CHAKRA</h1>
            <p className="text-[10px] text-blue-500 font-black tracking-[0.2em] uppercase mt-2">Dharma of Efficiency</p>
          </div>
          <div className="text-right">
             <div className="flex items-center gap-4 justify-end">
                <div className="text-right">
                  <p className="text-[8px] text-gray-500 uppercase tracking-widest font-bold">Total</p>
                  <p className="text-sm font-bold mono text-gray-400">{stats.total}</p>
                </div>
                <div className="text-right">
                  <p className="text-[8px] text-gray-500 uppercase tracking-widest font-bold">Passed</p>
                  <p className="text-sm font-black mono text-blue-400">{stats.current}</p>
                </div>
                <div className="text-right">
                  <p className="text-[8px] text-gray-500 uppercase tracking-widest font-bold">Left</p>
                  <p className="text-sm font-black mono text-orange-400">{stats.remaining}</p>
                </div>
             </div>
          </div>
        </div>

        {/* Global Progress Bar */}
        <div className="relative h-1.5 w-full bg-white/5 rounded-full overflow-hidden">
           <div 
             className="absolute top-0 left-0 h-full bg-blue-500 transition-all duration-1000 ease-linear shadow-[0_0_10px_rgba(59,130,246,0.5)]" 
             style={{ width: `${stats.percentPassed}%` }}
           />
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 p-4 space-y-4">
        {/* Date Selector / Calendar Bar */}
        <div className="glass p-3 rounded-2xl flex items-center justify-between border-white/10">
          <div className="flex items-center gap-3">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="text-gray-400"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
            <input 
              type="date" 
              value={selectedDate}
              onChange={(e) => setSelectedDate(e.target.value)}
              className="bg-transparent text-sm font-black uppercase text-white outline-none cursor-pointer tracking-wider"
            />
          </div>
          <div className="flex items-center gap-2">
            <span className="text-[9px] font-black text-gray-500 uppercase tracking-widest">Selected Date</span>
          </div>
        </div>

        {currentView === 'dashboard' && (
          <div className="space-y-4">
            {/* Completion Progress Bar */}
            <div className="glass p-5 rounded-2xl border-white/5">
               <div className="flex justify-between items-end mb-3">
                  <h2 className="text-[10px] font-black uppercase tracking-widest text-gray-500">Karam Completion Status</h2>
                  <span className="text-lg font-black text-white">{completionRate}%</span>
               </div>
               <div className="h-3 w-full bg-white/5 rounded-full p-0.5 border border-white/5">
                  <div 
                    className="h-full bg-emerald-500 rounded-full transition-all duration-700 shadow-[0_0_12px_rgba(16,185,129,0.3)]"
                    style={{ width: `${completionRate}%` }}
                  />
               </div>
            </div>

            <div className="grid grid-cols-1 gap-4">
              {BLOCKS.map(block => (
                <BlockCard 
                  key={block.id}
                  block={block}
                  activities={filteredActivities.filter(a => a.blockId === block.id)}
                  isActive={block.id === currentBlockId && selectedDate === new Date().toISOString().split('T')[0]}
                  onAdd={setActiveModalBlock}
                  onUpdateStatus={updateActivityStatus}
                  onReschedule={handleReschedule}
                />
              ))}
            </div>
          </div>
        )}

        {currentView === 'stats' && (
          <div className="space-y-6">
            <div className="glass p-6 rounded-3xl border border-white/5 text-center">
              <h2 className="text-sm font-black uppercase tracking-widest text-gray-400 mb-6">Aggregate Karma Mix</h2>
              <div className="h-64">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={Object.entries(activities.reduce((acc, curr) => {
                        acc[curr.type] = (acc[curr.type] || 0) + 1;
                        return acc;
                      }, {} as Record<string, number>)).map(([name, value]) => ({ name, value }))}
                      innerRadius={60}
                      outerRadius={80}
                      paddingAngle={5}
                      dataKey="value"
                    >
                      {Object.keys(ACTIVITY_COLORS).map((key, index) => (
                        <Cell key={`cell-${index}`} fill={ACTIVITY_COLORS[key as ActivityType]} />
                      ))}
                    </Pie>
                    <Tooltip 
                      contentStyle={{ backgroundColor: '#171717', border: '1px solid #333', borderRadius: '12px' }}
                      itemStyle={{ color: '#fff', fontSize: '12px' }}
                    />
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </div>
          </div>
        )}

        {currentView === 'coach' && (
          <div className="space-y-6">
            <div className="glass p-6 rounded-3xl border border-blue-500/30">
              <h2 className="text-lg font-black tracking-tight mb-2">Cycle Wisdom</h2>
              <p className="text-[10px] uppercase font-bold text-gray-500 mb-6 tracking-widest">Karma Chakra Logic Core</p>

              {!coachResponse && !isAnalyzing && (
                <button 
                  onClick={getCoachAdvice}
                  className="w-full py-5 bg-white text-black font-black rounded-2xl transition-all shadow-xl hover:scale-[1.02] active:scale-95 uppercase tracking-widest text-xs"
                >
                  Consult Intelligence
                </button>
              )}

              {isAnalyzing && (
                <div className="py-12 text-center space-y-6">
                  <div className="inline-block relative">
                     <div className="w-12 h-12 border-2 border-blue-500/20 rounded-full"></div>
                     <div className="absolute inset-0 border-t-2 border-blue-500 rounded-full animate-spin"></div>
                  </div>
                  <p className="text-[10px] text-blue-400 font-black animate-pulse uppercase tracking-[0.4em]">Optimizing Lifeline...</p>
                </div>
              )}

              {coachResponse && !isAnalyzing && (
                <div className="animate-in slide-in-from-bottom duration-500">
                  <div className="p-5 bg-white/5 rounded-2xl border border-white/10 text-sm text-gray-300 font-medium leading-relaxed">
                    {coachResponse.split('\n').map((line, i) => (
                       <p key={i} className="mb-2 last:mb-0">{line}</p>
                    ))}
                  </div>
                  <button 
                    onClick={() => setCoachResponse(null)}
                    className="w-full py-4 mt-4 text-[10px] uppercase font-black text-gray-600 hover:text-white transition-colors tracking-widest"
                  >
                    Reset Wisdom
                  </button>
                </div>
              )}
            </div>
          </div>
        )}
      </main>

      {/* Navigation Footer */}
      <nav className="fixed bottom-0 left-0 right-0 h-20 bg-[#0a0a0a]/95 backdrop-blur-2xl border-t border-white/5 flex items-center justify-around px-6 z-50">
        <button 
          onClick={() => setCurrentView('dashboard')}
          className={`flex flex-col items-center gap-1 transition-all ${currentView === 'dashboard' ? 'text-blue-500 scale-110' : 'text-gray-600 hover:text-gray-400'}`}
        >
          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><rect width="18" height="18" x="3" y="3" rx="2"/><path d="M3 9h18"/><path d="M9 21V9"/></svg>
          <span className="text-[9px] font-black uppercase tracking-widest">Karma</span>
        </button>

        <button 
          onClick={() => setCurrentView('stats')}
          className={`flex flex-col items-center gap-1 transition-all ${currentView === 'stats' ? 'text-emerald-500 scale-110' : 'text-gray-600 hover:text-gray-400'}`}
        >
          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M3 3v18h18"/><path d="m19 9-5 5-4-4-3 3"/></svg>
          <span className="text-[9px] font-black uppercase tracking-widest">Chakra</span>
        </button>

        <button 
          onClick={() => setCurrentView('coach')}
          className={`flex flex-col items-center gap-1 transition-all ${currentView === 'coach' ? 'text-purple-500 scale-110' : 'text-gray-600 hover:text-gray-400'}`}
        >
          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><circle cx="12" cy="12" r="10"/><path d="M12 16v-4"/><path d="M12 8h.01"/></svg>
          <span className="text-[9px] font-black uppercase tracking-widest">Dharma</span>
        </button>
      </nav>

      {/* Modals */}
      {activeModalBlock !== null && (
        <ActivityModal 
          blockId={activeModalBlock}
          onClose={() => setActiveModalBlock(null)}
          onSave={handleAddActivity}
        />
      )}
    </div>
  );
};

