}

import { ActivityType } from './types';

export const ACTIVITY_TYPES: ActivityType[] = ['Work', 'Study', 'Home', 'Sleep', 'Other'];

export const ACTIVITY_COLORS: Record<ActivityType, string> = {
  Work: '#3b82f6',   // Blue
  Study: '#8b5cf6',  // Purple
  Home: '#10b981',   // Emerald
  Sleep: '#6366f1',  // Indigo
  Other: '#6b7280',  // Gray
};

import React from 'react';
import { ActivityEntry, ActivityStatus } from '../types';
