  const isDone = activity.status === 'Completed';
  const totalMins = activity.estimatedDuration + (activity.overtime || 0);

  return (
    <div className={`p-4 rounded-2xl transition-all duration-300 glass border-white/5 ${isDone ? 'opacity-60' : ''}`}>
      <div className="flex justify-between items-start">
        <div className="flex-1">
          <div className="flex items-center gap-2 mb-1">
            <div 
              className="w-2 h-2 rounded-full" 
              style={{ backgroundColor: ACTIVITY_COLORS[activity.type] }}
