            <span className={`text-[10px] font-black uppercase tracking-widest ${isDone ? 'text-gray-500' : 'text-blue-400'}`}>
              {activity.type}
            </span>
          </div>
          <h3 className={`font-bold text-sm ${isDone ? 'line-through text-gray-500' : 'text-white'}`}>
            {activity.description}
          </h3>

          <div className="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-[10px] mono text-gray-500">
            <div className="flex items-center gap-1">
              <span className="font-bold uppercase text-[8px] text-gray-600">Target:</span>
              <span>{activity.estimatedDuration}m</span>
            </div>
            <div className="flex items-center gap-1">
              <span className="font-bold uppercase text-[8px] text-gray-600">Overtime:</span>
              <span className={activity.overtime > 0 ? 'text-orange-400' : ''}>{activity.overtime}m</span>
            </div>
            {isDone && (
              <div className="flex items-center gap-1">
                <span className="font-bold uppercase text-[8px] text-emerald-600">Total:</span>
                <span className="text-emerald-500">{totalMins}m</span>
              </div>
            )}
          </div>
        </div>

        <div className="flex gap-2">
          {activity.status === 'Pending' && (
            <>
              <button 
                onClick={() => onUpdateStatus(activity.id, 'Completed')}
                className="p-2 hover:bg-emerald-500/20 text-emerald-500 rounded-xl transition-colors border border-emerald-500/10"
                title="Mark Complete"
              >
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><polyline points="20 6 9 17 4 12"/></svg>
              </button>
              <button 
                onClick={() => onMoveDate(activity.id)}
                className="p-2 hover:bg-orange-500/20 text-orange-400 rounded-xl transition-colors border border-orange-500/10"
                title="Move to Tomorrow"
              >
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="M5 12h14"/><path d="m12 5 7 7-7 7"/></svg>
              </button>
            </>
          )}
          {activity.status === 'Completed' && (
            <span className="text-[9px] bg-emerald-500/20 text-emerald-500 font-black px-2 py-1 rounded-lg uppercase border border-emerald-500/20">Finalized</span>
          )}
          {activity.status === 'Rescheduled' && (
            <span className="text-[9px] bg-orange-500/20 text-orange-400 font-black px-2 py-1 rounded-lg uppercase border border-orange-500/20">Rescheduled</span>
          )}
        </div>
      </div>
    </div>
  );
};

