              className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-4 text-sm focus:outline-none focus:ring-1 focus:ring-blue-500 text-white font-medium placeholder:text-gray-700"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
             <div className="space-y-1">
                <label className="block text-[10px] uppercase text-gray-500 font-black mb-2 tracking-[0.2em]">Target (Mins)</label>
                <input
                  type="number"
                  value={duration}
                  onChange={(e) => setDuration(e.target.value)}
                  className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-4 text-sm focus:outline-none focus:ring-1 focus:ring-blue-500 text-white mono"
                />
             </div>
             <div className="space-y-1">
                <label className="block text-[10px] uppercase text-gray-500 font-black mb-2 tracking-[0.2em]">Overtime (Mins)</label>
                <input
                  type="number"
                  value={overtime}
                  onChange={(e) => setOvertime(e.target.value)}
                  className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-4 text-sm focus:outline-none focus:ring-1 focus:ring-orange-500 text-white mono"
                />
             </div>
          </div>

          <div className="p-4 bg-white/5 rounded-2xl border border-white/5">
            <label className="block text-[10px] uppercase text-gray-500 font-black mb-4 tracking-[0.2em]">Batch Duplication</label>
            <div className="flex gap-6">
              <label className="flex items-center gap-3 cursor-pointer group">
                <div className="relative">
                  <input 
                    type="checkbox" 
                    checked={repeatMode === 'weekdays'} 
                    onChange={() => setRepeatMode(prev => prev === 'weekdays' ? 'none' : 'weekdays')}
                    className="peer hidden"
                  />
                  <div className="w-5 h-5 border-2 border-white/20 rounded peer-checked:bg-blue-600 peer-checked:border-blue-400 transition-all flex items-center justify-center">
                    {repeatMode === 'weekdays' && <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4"><polyline points="20 6 9 17 4 12"/></svg>}
                  </div>
                </div>
                <span className="text-xs font-bold text-gray-400 group-hover:text-white transition-colors">Weekdays</span>
              </label>
              <label className="flex items-center gap-3 cursor-pointer group">
                <div className="relative">
                  <input 
                    type="checkbox" 
                    checked={repeatMode === 'weekends'} 
                    onChange={() => setRepeatMode(prev => prev === 'weekends' ? 'none' : 'weekends')}
                    className="peer hidden"
                  />
                  <div className="w-5 h-5 border-2 border-white/20 rounded peer-checked:bg-blue-600 peer-checked:border-blue-400 transition-all flex items-center justify-center">
                    {repeatMode === 'weekends' && <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4"><polyline points="20 6 9 17 4 12"/></svg>}
                  </div>
                </div>
                <span className="text-xs font-bold text-gray-400 group-hover:text-white transition-colors">Weekends</span>
              </label>
            </div>
          </div>
        </div>

        <div className="flex gap-3 mt-10">
          <button 
            onClick={onClose}
            className="flex-1 py-4 text-[10px] text-gray-600 hover:text-white transition-colors uppercase font-black tracking-[0.2em]"
          >
            Discard
          </button>
          <button 
            onClick={() => onSave(type, description, parseInt(duration) || 0, parseInt(overtime) || 0, repeatMode)}
            disabled={!description.trim()}
            className="flex-[2] py-4 bg-white text-black font-black rounded-2xl transition-all disabled:opacity-50 disabled:cursor-not-allowed uppercase tracking-widest text-[10px] shadow-xl shadow-white/10 active:scale-95 hover:bg-gray-200"
          >
            Record Cycle
          </button>
        </div>
      </div>
    </div>
  );
};

export default ActivityModal;

import React, { useState, useEffect, useMemo } from 'react';
import { ActivityEntry, ActivityType, ActivityStatus, AppState, ReportInterval } from './types';
import { ACTIVITY_TYPES, ACTIVITY_COLORS } from './constants';
import ActivityItem from './components/ActivityItem';
import ActivityModal from './components/ActivityModal';
import { getProductivityAnalysis } from './services/geminiService';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip, BarChart, Bar, XAxis, YAxis, CartesianGrid } from 'recharts';

const App: React.FC = () => {
  const [activities, setActivities] = useState<ActivityEntry[]>([]);
  const [currentView, setCurrentView] = useState<AppState['currentView']>('dashboard');
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [reportInterval, setReportInterval] = useState<ReportInterval>('Daily');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [coachResponse, setCoachResponse] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('karma_chakra_v3_datewise');
    if (saved) setActivities(JSON.parse(saved));

    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    localStorage.setItem('karma_chakra_v3_datewise', JSON.stringify(activities));
  }, [activities]);

  const stats = useMemo(() => {
    const currentMins = currentTime.getHours() * 60 + currentTime.getMinutes();
    const totalMins = 24 * 60;
    const remainingMins = totalMins - currentMins;

    const format = (m: number) => {
      const h = Math.floor(m / 60);
      const min = m % 60;
      return `${h.toString().padStart(2, '0')}:${min.toString().padStart(2, '0')}`;
    };

    return {
      total: '24:00',
      current: format(currentMins),
      remaining: format(remainingMins),
      percentPassed: (currentMins / totalMins) * 100
    };
  }, [currentTime]);

  const handleAddActivity = (type: ActivityType, description: string, duration: number, overtime: number, repeatMode: 'none' | 'weekdays' | 'weekends') => {
    const datesToCreate: string[] = [selectedDate];

    if (repeatMode !== 'none') {
      const baseDate = new Date(selectedDate);
      const dayOfWeek = baseDate.getDay();
      const diff = baseDate.getDate() - dayOfWeek + (dayOfWeek === 0 ? -6 : 1);
      const startOfWeek = new Date(baseDate.setDate(diff));

      for (let i = 0; i < 7; i++) {
        const d = new Date(startOfWeek);
        d.setDate(startOfWeek.getDate() + i);
        const dateStr = d.toISOString().split('T')[0];
        if (dateStr === selectedDate) continue;

        const isWeekend = d.getDay() === 0 || d.getDay() === 6;
        if (repeatMode === 'weekdays' && !isWeekend) datesToCreate.push(dateStr);
        if (repeatMode === 'weekends' && isWeekend) datesToCreate.push(dateStr);
      }
    }

    const newEntries: ActivityEntry[] = datesToCreate.map(date => ({
      id: Math.random().toString(36).substr(2, 9),
      date,
      type,
      description,
      timestamp: Date.now(),
      estimatedDuration: duration,
      overtime: overtime,
      status: 'Pending',
    }));

    setActivities(prev => [...prev, ...newEntries]);
    setIsModalOpen(false);
  };

  const updateActivityStatus = (id: string, status: ActivityStatus) => {
    setActivities(prev => prev.map(a => a.id === id ? { ...a, status } : a));
  };

  const handleMoveToTomorrow = (id: string) => {
    setActivities(prev => {
      const activity = prev.find(a => a.id === id);
      if (!activity) return prev;

      const d = new Date(activity.date);
      d.setDate(d.getDate() + 1);
      const targetDate = d.toISOString().split('T')[0];

      const reschedEntry: ActivityEntry = {
        ...activity,
        id: Math.random().toString(36).substr(2, 9),
        date: targetDate,
        status: 'Pending',
        timestamp: Date.now(),
        rescheduledTo: targetDate
      };

      return prev.map(a => a.id === id ? { ...a, status: 'Rescheduled' } : a).concat(reschedEntry);
    });
  };

  const dailyActivities = useMemo(() => {
    return activities.filter(a => a.date === selectedDate);
  }, [activities, selectedDate]);

  const completionRate = useMemo(() => {
    if (dailyActivities.length === 0) return 0;
    const completed = dailyActivities.filter(a => a.status === 'Completed').length;
    return Math.round((completed / dailyActivities.length) * 100);
  }, [dailyActivities]);

  // Enhanced Report Logic
  const reportData = useMemo(() => {
    const now = new Date(selectedDate);
    const filterByInterval = (a: ActivityEntry) => {
      const activityDate = new Date(a.date);
      if (reportInterval === 'Daily') return a.date === selectedDate;
      if (reportInterval === 'Weekly') {
        const diff = (now.getTime() - activityDate.getTime()) / (1000 * 3600 * 24);
        return diff >= 0 && diff < 7;
      }
      if (reportInterval === 'Monthly') return activityDate.getMonth() === now.getMonth() && activityDate.getFullYear() === now.getFullYear();
      if (reportInterval === 'Quarterly') {
        const quarterNow = Math.floor(now.getMonth() / 3);
        const quarterAct = Math.floor(activityDate.getMonth() / 3);
        return quarterNow === quarterAct && activityDate.getFullYear() === now.getFullYear();
      }
      if (reportInterval === 'Half-Yearly') {
        const halfNow = now.getMonth() < 6 ? 0 : 1;
        const halfAct = activityDate.getMonth() < 6 ? 0 : 1;
        return halfNow === halfAct && activityDate.getFullYear() === now.getFullYear();
      }
      if (reportInterval === 'Yearly') return activityDate.getFullYear() === now.getFullYear();
      return false;
    };

    const intervalActivities = activities.filter(filterByInterval);
    const summary = intervalActivities.reduce((acc, curr) => {
      acc[curr.type] = (acc[curr.type] || 0) + (curr.estimatedDuration + curr.overtime);
      return acc;
    }, {} as Record<string, number>);

    return Object.entries(summary).map(([name, value]) => ({ name, value }));
  }, [activities, selectedDate, reportInterval]);

  const getCoachAdvice = async () => {
    setIsAnalyzing(true);
    const advice = await getProductivityAnalysis(dailyActivities);
    setCoachResponse(advice);
    setIsAnalyzing(false);
  };

  return (
    <div className="min-h-screen flex flex-col max-w-lg mx-auto pb-24 selection:bg-blue-500/30">
      {/* KARMA CHAKRA HEADER */}
      <header className="p-6 pt-10 sticky top-0 z-40 bg-[#0a0a0a]/90 backdrop-blur-xl border-b border-white/5">
        <div className="flex justify-between items-start mb-6">
          <div>
            <h1 className="text-3xl font-black tracking-tighter text-white leading-none">KARMA CHAKRA</h1>
            <p className="text-[10px] text-blue-500 font-black tracking-[0.2em] uppercase mt-2">Personal Dharma Log</p>
          </div>
          <div className="text-right flex flex-col items-end gap-1">
             <div className="flex items-center gap-4">
                <div className="text-right">
                  <p className="text-[8px] text-gray-600 uppercase tracking-widest font-black">Total</p>
                  <p className="text-sm font-bold mono text-gray-500">{stats.total}</p>
                </div>
                <div className="text-right">
                  <p className="text-[8px] text-gray-600 uppercase tracking-widest font-black">Now</p>
                  <p className="text-sm font-black mono text-blue-400">{stats.current}</p>
                </div>
                <div className="text-right">
                  <p className="text-[8px] text-gray-600 uppercase tracking-widest font-black">Left</p>
                  <p className="text-sm font-black mono text-orange-400">{stats.remaining}</p>
                </div>
             </div>
             <p className="text-[8px] text-gray-700 uppercase tracking-[0.3em] font-black mt-1">Status: Balanced Time</p>
          </div>
        </div>

        {/* Global Progress Bar */}
        <div className="relative h-1.5 w-full bg-white/5 rounded-full overflow-hidden">
           <div 
             className="absolute top-0 left-0 h-full bg-blue-500 transition-all duration-1000 ease-linear shadow-[0_0_10px_rgba(59,130,246,0.6)]" 
             style={{ width: `${stats.percentPassed}%` }}
           />
        </div>
      </header>

      {/* MAIN VIEWPORT */}
      <main className="flex-1 p-4 space-y-6">
        {currentView === 'dashboard' && (
          <>
            {/* Date Pick Section */}
            <div className="glass p-4 rounded-3xl flex items-center justify-between border-white/10 group transition-all hover:border-blue-500/30">
              <div className="flex items-center gap-4">
                <div className="p-2 bg-white/5 rounded-xl border border-white/10 text-blue-500">
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
                </div>
                <input 
                  type="date" 
                  value={selectedDate}
                  onChange={(e) => setSelectedDate(e.target.value)}
                  className="bg-transparent text-lg font-black uppercase text-white outline-none cursor-pointer tracking-tighter"
                />
              </div>
              <button 
                onClick={() => setIsModalOpen(true)}
                className="p-3 bg-white text-black rounded-2xl shadow-xl active:scale-95 transition-all"
              >
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
              </button>
            </div>

            {/* Completion Status Bar */}
            <div className="p-1">
               <div className="flex justify-between items-end mb-2">
                  <h2 className="text-[10px] font-black uppercase tracking-widest text-gray-500 px-1">Daily Completion Path</h2>
                  <span className="text-xl font-black text-white italic">{completionRate}%</span>
               </div>
               <div className="h-4 w-full bg-white/5 rounded-full p-1 border border-white/5 relative overflow-hidden">
                  <div 
                    className="h-full bg-emerald-500 rounded-full transition-all duration-700 ease-out shadow-[0_0_20px_rgba(16,185,129,0.4)]"
                    style={{ width: `${completionRate}%` }}
                  />
               </div>
            </div>

            {/* Daily Task List */}
            <div className="space-y-4">
              {dailyActivities.length > 0 ? (
                dailyActivities.map(activity => (
                  <ActivityItem 
                    key={activity.id}
                    activity={activity}
                    onUpdateStatus={updateActivityStatus}
                    onMoveDate={handleMoveToTomorrow}
                  />
                ))
              ) : (
                <div className="py-20 text-center space-y-4 glass rounded-3xl border-dashed border-white/5 opacity-50">
                  <div className="inline-block p-4 bg-white/5 rounded-full text-gray-600">
                    <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
                  </div>
                  <p className="text-xs font-black uppercase tracking-[0.3em] text-gray-600">No Karma recorded for this date</p>
                </div>
              )}
            </div>
          </>
        )}

        {currentView === 'stats' && (
          <div className="space-y-6">
            <div className="glass p-6 rounded-3xl border border-white/5">
              <div className="flex justify-between items-center mb-8">
                <h2 className="text-sm font-black uppercase tracking-widest text-gray-400">Karma Chakra Reports</h2>
                <select 
                  value={reportInterval}
                  onChange={(e) => setReportInterval(e.target.value as ReportInterval)}
                  className="bg-white/5 border border-white/10 rounded-xl px-4 py-2 text-xs font-black text-white outline-none cursor-pointer hover:bg-white/10"
                >
                  <option className="bg-[#171717]" value="Daily">Daily</option>
                  <option className="bg-[#171717]" value="Weekly">Weekly</option>
                  <option className="bg-[#171717]" value="Monthly">Monthly</option>
                  <option className="bg-[#171717]" value="Quarterly">Quarterly</option>
                  <option className="bg-[#171717]" value="Half-Yearly">Half-Yearly</option>
                  <option className="bg-[#171717]" value="Yearly">Yearly</option>
                </select>
              </div>

              {reportData.length > 0 ? (
                <div className="space-y-8">
                   <div className="h-64">
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie
                          data={reportData}
                          innerRadius={60}
                          outerRadius={85}
                          paddingAngle={8}
                          dataKey="value"
                        >
                          {reportData.map((entry, index) => (
                            <Cell key={`cell-${index}`} fill={ACTIVITY_COLORS[entry.name as ActivityType]} stroke="none" />
                          ))}
                        </Pie>
                        <Tooltip 
                          contentStyle={{ backgroundColor: '#171717', border: '1px solid #333', borderRadius: '16px', fontWeight: 'bold' }}
                          itemStyle={{ color: '#fff', fontSize: '12px' }}
                          formatter={(value: number) => [`${value} mins`, 'Intensity']}
                        />
                      </PieChart>
                    </ResponsiveContainer>
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                    {reportData.map((d) => (
                      <div key={d.name} className="p-4 bg-white/5 rounded-2xl border border-white/5 flex flex-col items-center">
                        <div className="w-2 h-2 rounded-full mb-2" style={{ backgroundColor: ACTIVITY_COLORS[d.name as ActivityType] }} />
                        <span className="text-[10px] font-black uppercase text-gray-500 mb-1">{d.name}</span>
                        <span className="text-lg font-black text-white italic">{d.value}m</span>
                      </div>
                    ))}
                  </div>
                </div>
              ) : (
                <div className="py-20 text-center italic text-gray-600 text-xs tracking-widest">
                  Cycle empty for the selected interval
                </div>
              )}
            </div>
          </div>
        )}

        {currentView === 'coach' && (
          <div className="space-y-6 animate-in slide-in-from-bottom duration-500">
            <div className="glass p-6 rounded-3xl border border-blue-500/30">
              <h2 className="text-xl font-black tracking-tighter mb-2 text-white italic">DHARMA COUNSEL</h2>
              <p className="text-[10px] uppercase font-bold text-gray-600 mb-8 tracking-[0.4em]">Logic-Driven Optimization</p>

              {!coachResponse && !isAnalyzing && (
                <button 
                  onClick={getCoachAdvice}
                  className="w-full py-6 bg-white text-black font-black rounded-2xl transition-all shadow-xl hover:scale-[1.02] active:scale-95 uppercase tracking-widest text-[11px]"
                >
                  Consult Intelligence
                </button>
              )}

              {isAnalyzing && (
                <div className="py-20 text-center space-y-8">
                  <div className="relative inline-block">
                     <div className="w-16 h-16 border-4 border-blue-500/20 rounded-full"></div>
                     <div className="absolute inset-0 border-t-4 border-blue-500 rounded-full animate-spin"></div>
                  </div>
                  <p className="text-[10px] text-blue-400 font-black animate-pulse uppercase tracking-[0.5em]">Synchronizing Soul & Skill...</p>
                </div>
              )}

              {coachResponse && !isAnalyzing && (
                <div className="space-y-4">
                  <div className="p-6 bg-white/5 rounded-2xl border border-white/10 text-sm text-gray-300 font-medium leading-relaxed shadow-inner">
                    {coachResponse.split('\n').map((line, i) => (
                       <p key={i} className="mb-2 last:mb-0">{line}</p>
                    ))}
                  </div>
                  <button 
                    onClick={() => setCoachResponse(null)}
                    className="w-full py-4 text-[10px] uppercase font-black text-gray-700 hover:text-white transition-colors tracking-[0.3em]"
                  >
                    Close Session
                  </button>
                </div>
              )}
            </div>
          </div>
        )}
      </main>

      {/* FIXED NAV FOOTER */}
      <nav className="fixed bottom-0 left-0 right-0 h-24 bg-[#0a0a0a]/95 backdrop-blur-3xl border-t border-white/5 flex items-center justify-around px-8 z-50">
        <button 
          onClick={() => setCurrentView('dashboard')}
          className={`flex flex-col items-center gap-2 transition-all ${currentView === 'dashboard' ? 'text-blue-500 scale-110' : 'text-gray-700 hover:text-gray-400'}`}
        >
          <div className="p-2 rounded-xl transition-all">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><rect width="18" height="18" x="3" y="3" rx="2"/><path d="M3 9h18"/><path d="M9 21V9"/></svg>
          </div>
          <span className="text-[9px] font-black uppercase tracking-[0.3em]">Karma</span>
        </button>

        <button 
          onClick={() => setCurrentView('stats')}
          className={`flex flex-col items-center gap-2 transition-all ${currentView === 'stats' ? 'text-emerald-500 scale-110' : 'text-gray-700 hover:text-gray-400'}`}
        >
          <div className="p-2 rounded-xl transition-all">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M12 2v20"/><path d="m17 17 5-5-5-5"/><path d="m7 7-5 5 5 5"/></svg>
          </div>
          <span className="text-[9px] font-black uppercase tracking-[0.3em]">Chakra</span>
        </button>

        <button 
          onClick={() => setCurrentView('coach')}
          className={`flex flex-col items-center gap-2 transition-all ${currentView === 'coach' ? 'text-purple-500 scale-110' : 'text-gray-700 hover:text-gray-400'}`}
        >
          <div className="p-2 rounded-xl transition-all">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><circle cx="12" cy="12" r="10"/><path d="M12 16v-4"/><path d="M12 8h.01"/></svg>
          </div>
          <span className="text-[9px] font-black uppercase tracking-[0.3em]">Dharma</span>
        </button>
      </nav>

      {/* MODAL OVERLAYS */}
      {isModalOpen && (
        <ActivityModal 
          onClose={() => setIsModalOpen(false)}
          onSave={handleAddActivity}
        />
      )}
    </div>
  );
};

export default App;

export type ActivityType = 'Work' | 'Study' | 'Home' | 'Sleep' | 'Other';
export type ActivityStatus = 'Pending' | 'Completed' | 'Rescheduled';
export type ReportInterval = 'Daily' | 'Weekly' | 'Monthly' | 'Quarterly' | 'Half-Yearly' | 'Yearly';

// Added TimeBlock interface to support the 6x4 cycle structure
export interface TimeBlock {
  id: number;
  label: string;
  startTime: string;
  endTime: string;
}

export interface ActivityEntry {
  id: string;
  date: string; // YYYY-MM-DD
  type: ActivityType;
  description: string;
  timestamp: number;
  estimatedDuration: number; // minutes
  overtime: number; // minutes
  status: ActivityStatus;
  rescheduledTo?: string; // date string
  // Added optional blockId to associate activities with specific time blocks
  blockId?: number;
}

export interface AppState {
  activities: ActivityEntry[];
  currentView: 'dashboard' | 'stats' | 'coach';
  selectedDate: string;
  reportInterval: ReportInterval;
}

import { ActivityType, TimeBlock } from './types';

export const ACTIVITY_TYPES: ActivityType[] = ['Work', 'Study', 'Home', 'Sleep', 'Other'];

export const ACTIVITY_COLORS: Record<ActivityType, string> = {
  Work: '#3b82f6',   // Blue
  Study: '#8b5cf6',  // Purple
  Home: '#10b981',   // Emerald
  Sleep: '#6366f1',  // Indigo
  Other: '#6b7280',  // Gray
};

// Added BLOCKS constant defining the six 4-hour cycles (6x4 = 24 hours) for the Karma Chakra structure
export const BLOCKS: TimeBlock[] = [
  { id: 1, label: 'Brahma Muhurta', startTime: '04:00', endTime: '08:00' },
  { id: 2, label: 'Pratah', startTime: '08:00', endTime: '12:00' },
  { id: 3, label: 'Madhyahna', startTime: '12:00', endTime: '16:00' },
  { id: 4, label: 'Aparahna', startTime: '16:00', endTime: '20:00' },
  { id: 5, label: 'Sayahna', startTime: '20:00', endTime: '00:00' },
