  }, [initialData]);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/90 backdrop-blur-md">
      <div className="w-full max-w-md glass p-6 rounded-3xl border border-white/10 shadow-2xl">
