            className="flex-[2] py-4 bg-white text-black font-black rounded-2xl transition-all disabled:opacity-50 disabled:cursor-not-allowed uppercase tracking-widest text-[10px] shadow-xl shadow-white/10 active:scale-95"
          >
            {initialData ? 'Update Karma' : 'Record Cycle'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default ActivityModal;

export type ActivityType = 'Work' | 'Study' | 'Home' | 'Sleep' | 'Workout' | 'Other';
export type ActivityStatus = 'Pending' | 'Completed' | 'Rescheduled';
export type ReportInterval = 'Daily' | 'Weekly' | 'Monthly' | 'Quarterly' | 'Half-Yearly' | 'Yearly';

export interface TimeBlock {
  id: number;
  label: string;
  startTime: string;
  endTime: string;
}

export interface TimerState {
  isActive: boolean;
  lastStartTime: number | null;
  totalElapsed: number; // in milliseconds
}

export interface ActivityEntry {
  id: string;
  date: string; // YYYY-MM-DD
  type: ActivityType;
  description: string;
  timestamp: number;
  estimatedDuration: number; // minutes
  overtime: number; // minutes
  status: ActivityStatus;
  rescheduledTo?: string; // date string
  movedFromDate?: string; // date string
  movedAt?: number; // timestamp
  blockId?: number;
  timer?: TimerState;
}

export interface AppState {
  activities: ActivityEntry[];
  currentView: 'dashboard' | 'stats' | 'coach' | 'backlog';
  selectedDate: string;
  reportInterval: ReportInterval;
}

import { ActivityType, TimeBlock } from './types';

export const ACTIVITY_TYPES: ActivityType[] = ['Work', 'Study', 'Home', 'Sleep', 'Workout', 'Other'];

export const ACTIVITY_COLORS: Record<ActivityType, string> = {
  Work: '#3b82f6',    // Bright Blue
  Study: '#f59e0b',   // Amber/Orange-Yellow
  Home: '#10b981',    // Emerald Green
  Sleep: '#8b5cf6',   // Vivid Purple
  Workout: '#ef4444', // Vibrant Red
  Other: '#ec4899',   // Pink/Magenta
};

// Added BLOCKS constant defining the six 4-hour cycles (6x4 = 24 hours) for the Karma Chakra structure
export const BLOCKS: TimeBlock[] = [
  { id: 1, label: 'Brahma Muhurta', startTime: '04:00', endTime: '08:00' },
  { id: 2, label: 'Pratah', startTime: '08:00', endTime: '12:00' },
  { id: 3, label: 'Madhyahna', startTime: '12:00', endTime: '16:00' },
  { id: 4, label: 'Aparahna', startTime: '16:00', endTime: '20:00' },
  { id: 5, label: 'Sayahna', startTime: '20:00', endTime: '00:00' },
  { id: 6, label: 'Nishita', startTime: '00:00', endTime: '04:00' },
];

export type ActivityType = 'Work' | 'Study' | 'Home' | 'Sleep' | 'Workout' | 'Other';
export type ActivityStatus = 'Pending' | 'Completed' | 'Rescheduled';
export type ReportInterval = 'Daily' | 'Weekly' | 'Monthly' | 'Quarterly' | 'Half-Yearly' | 'Yearly';

export interface TimeBlock {
  id: number;
  label: string;
  startTime: string;
  endTime: string;
}

export interface TimerState {
  isActive: boolean;
  lastStartTime: number | null;
  totalElapsed: number; // in milliseconds
}

export interface ActivityEntry {
  id: string;
  date: string; // YYYY-MM-DD
  type: ActivityType;
  description: string;
  timestamp: number;
  estimatedDuration: number; // minutes
  overtime: number; // minutes
  status: ActivityStatus;
  rescheduledTo?: string; // date string
  movedFromDate?: string; // date string
  movedAt?: number; // timestamp
  blockId?: number;
  timer?: TimerState;
  startTime?: string; // HH:mm format
  alarmEnabled?: boolean;
}

export interface AppState {
  activities: ActivityEntry[];
  currentView: 'dashboard' | 'stats' | 'coach' | 'backlog';
  selectedDate: string;
  reportInterval: ReportInterval;
}

